Rules.InvariantScript:
Set(varAppView, "Config");
Set(varPageKey, "CONFIG");
Set(varPageTitle, "Configuration");
Set(varPageSubtitle, "Report structure and scope management");

Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingSubMsg, "");
Set(varGlobalLoadingScope, "");

Set(varCfg_SelectedSection, "TASKS");
Set(varConfigLoaded, Coalesce(varConfigLoaded, false));
Set(varCfg_IsLoading, Coalesce(varCfg_IsLoading, false));
Set(varTreeSearch, Coalesce(Text(varTreeSearch), ""));

Set(varCfgPunches_Loaded, Coalesce(varCfgPunches_Loaded, false));
Set(varCfgPunches_IsLoading, Coalesce(varCfgPunches_IsLoading, false));
Set(varCfgPunches_IsSaving, Coalesce(varCfgPunches_IsSaving, false));
Set(varCfgPunches_IsApplying, Coalesce(varCfgPunches_IsApplying, false));
Set(varCfgPunches_Error, Coalesce(Text(varCfgPunches_Error), ""));

Set(varLastSavedNodeId, Coalesce(Text(varLastSavedNodeId), ""));
Set(varScopeModalOpen, false);
Set(varScopeModalLoading, false);
Set(varScopeConfirmCloseOpen, false);
Set(varScopeModalDirty, false);
Set(varScopeModalSearch, "");
Set(varScopeModalError, "");

ClearCollect(
    colScopeModalSchema,
    FirstN(
        Table(
            {
                GroupKey: "",
                PhaseName: "",
                ElementDiscipline: "",
                ElementLevel: "",
                FormName: "",
                FormDescription: "",
                Sct: false,
                MasterTask: false,
                DossierTask: false,
                TotalInspections: 0,
                AssignedNodeId: "",
                L1DisplayName: "",
                L2DisplayName: "",
                L3DisplayName: ""
            }
        ),
        0
    )
);

ClearCollect(
    colScopeModalTarget,
    FirstN(
        Table(
            {
                NodeId: "",
                L1DisplayName: "",
                L2DisplayName: "",
                L3DisplayName: "",
                AssignedCount: 0,
                AvailableCount: 0
            }
        ),
        0
    )
);

ClearCollect(colScopeModalAvailable, colScopeModalSchema);
ClearCollect(colScopeModalAssigned, colScopeModalSchema);
ClearCollect(colScopeModalOriginalAssigned, colScopeModalSchema);
ClearCollect(colScopeModalSelectedAvailable, colScopeModalSchema);
ClearCollect(colScopeModalSelectedAssigned, colScopeModalSchema);
ClearCollect(colScopeModalToAssign, colScopeModalSchema);
ClearCollect(colScopeModalToUnassign, colScopeModalSchema);

ControlPropertyState.AutoRuleBindingString:
Set(varAppView, "Config");
Set(varPageKey, "CONFIG");
Set(varPageTitle, "Configuration");
Set(varPageSubtitle, "Report structure and scope management");
Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingSubMsg, "");
Set(varGlobalLoadingScope, "");
Set(varCfg_SelectedSection, "TASKS");
Set(varConfigLoaded, Coalesce(varConfigLoaded, false));
Set(varCfg_IsLoading, Coalesce(varCfg_IsLoading, false));
Set(varTreeSearch, Coalesce(Text(varTreeSearch), ""));
Set(varCfgPunches_Loaded, Coalesce(varCfgPunches_Loaded, false));
Set(varCfgPunches_IsLoading, Coalesce(varCfgPunches_IsLoading, false));
Set(varCfgPunches_IsSaving, Coalesce(varCfgPunches_IsSaving, false));
Set(varCfgPunches_IsApplying, Coalesce(varCfgPunches_IsApplying, false));
Set(varCfgPunches_Error, Coalesce(Text(varCfgPunches_Error), ""));

Rules.InvariantScript:
If(
    IsBlank(varProjectId),
    Notify("Please select a project first.", NotificationType.Warning);
    Set(varCfg_IsLoading, false);
    Set(varGlobalLoading, false);
    Exit()
);

If(
    varCfg_IsLoading,
    Notify("Configuration is already loading.", NotificationType.Information);
    Exit()
);

Set(varCfg_IsLoading, true);
Set(varCfg_Error, "");

Set(varGlobalLoading, true);
Set(varGlobalLoadingMsg, "Loading Configuration...");
Set(varGlobalLoadingSubMsg, "Loading report tree, scope and assignments");
Set(varGlobalLoadingScope, "CONFIG");

ClearCollect(colCfgErrors, Table({Step: "", Message: ""}));
Clear(colCfgErrors);

ClearCollect(colNodes_Staging, FirstN(colNodes, 0));
ClearCollect(colAssign_Staging, FirstN(colAssign, 0));
ClearCollect(colScope_Staging, FirstN(colScope, 0));

/* 1) Tree */
IfError(
    ClearCollect(
        colNodes_Staging,
        ForAll(
            Table(ParseJSON(Coalesce(WarRoom_ReportConfig_GetTree.Run(varProjectId).result, "[]"))),
            {
                NodeId: Text(Value.NodeId),
                ProjectId: If(IsBlank(Text(Value.ProjectId)) || Text(Value.ProjectId) = "null", varProjectId, Value(Text(Value.ProjectId))),
                LevelNo: If(IsBlank(Text(Value.LevelNo)) || Text(Value.LevelNo) = "null", 0, Value(Text(Value.LevelNo))),
                ParentNodeId: Text(Value.ParentNodeId),
                DisplayName: Text(Value.DisplayName),
                Description: Text(Value.Description),
                SqlKey: Text(Value.SqlKey),
                GridKey: Text(Value.GridKey),
                SortOrder: If(IsBlank(Text(Value.SortOrder)) || Text(Value.SortOrder) = "null", 0, Value(Text(Value.SortOrder))),
                IsActive: Boolean(Value.IsActive)
            }
        )
    ),
    ClearCollect(
        colCfgErrors,
        {
            Step: "Tree",
            Message: "Error loading report tree: " & FirstError.Message
        }
    )
);

/* 2) Assignments */
If(
    CountRows(colCfgErrors) = 0,
    IfError(
        ClearCollect(
            colAssign_Staging,
            ForAll(
                Table(ParseJSON(Coalesce(WarRoom_ReportConfig_GetAssignments.Run(varProjectId).result, "[]"))),
                {
                    AssignmentId: Text(Value.AssignmentId),
                    ProjectId: If(IsBlank(Text(Value.ProjectId)) || Text(Value.ProjectId) = "null", varProjectId, Value(Text(Value.ProjectId))),
                    GroupKey: Text(Value.GroupKey),
                    NodeId: Text(Value.NodeId),
                    CreatedOn: Text(Value.CreatedOn),
                    CreatedBy: Text(Value.CreatedBy)
                }
            )
        ),
        ClearCollect(
            colCfgErrors,
            {
                Step: "Assignments",
                Message: "Error loading assignments: " & FirstError.Message
            }
        )
    )
);

/* 3) Scope */
If(
    CountRows(colCfgErrors) = 0,
    IfError(
        ClearCollect(
            colScope_Staging,
            ForAll(
                Table(ParseJSON(Coalesce(WarRoom_ReportConfig_GetScope.Run(varProjectId).result, "[]"))),
                {
                    GroupKey: Text(Value.GroupKey),
                    ElementDiscipline: Text(Value.ElementDiscipline),
                    ElementLevel: Text(Value.ElementLevel),
                    PhaseName: Text(Value.PhaseName),
                    FormName: Text(Value.FormName),
                    FormDescription: Text(Value.FormDescription),
                    Sct: Boolean(Value.Sct),
                    MasterTask: Boolean(Value.MasterTask),
                    DossierTask: Boolean(Value.DossierTask),
                    TotalInspections: If(IsBlank(Text(Value.TotalInspections)) || Text(Value.TotalInspections) = "null", 0, Value(Text(Value.TotalInspections)))
                }
            )
        ),
        ClearCollect(
            colCfgErrors,
            {
                Step: "Scope",
                Message: "Error loading project scope: " & FirstError.Message
            }
        )
    )
);

/* 4) Commit */
If(
    CountRows(colCfgErrors) = 0,

    ClearCollect(colNodes, colNodes_Staging);
    ClearCollect(colAssign, colAssign_Staging);
    ClearCollect(colScope, colScope_Staging);

    Clear(colAssignedForTarget);
    Clear(colAssignedForTargetSummary);
    Clear(colConfigTreeRows);

    ForAll(
        SortByColumns(
            Filter(colNodes, IsActive && LevelNo = 1),
            "SortOrder",
            SortOrder.Ascending,
            "DisplayName",
            SortOrder.Ascending
        ) As l1,

        Collect(
            colConfigTreeRows,
            {
                RowNodeId: Text(l1.NodeId),
                RowParentNodeId: Text(l1.ParentNodeId),
                RowLevel: 1,
                RowLabel: Text(l1.DisplayName),
                RowDescription: Text(l1.Description),
                RowSortPath: Text(l1.SortOrder, "000") & ".000.000",
                RowIcon: "Header"
            }
        );

        ForAll(
            SortByColumns(
                Filter(
                    colNodes,
                    IsActive &&
                    LevelNo = 2 &&
                    Text(ParentNodeId) = Text(l1.NodeId)
                ),
                "SortOrder",
                SortOrder.Ascending,
                "DisplayName",
                SortOrder.Ascending
            ) As l2,

            Collect(
                colConfigTreeRows,
                {
                    RowNodeId: Text(l2.NodeId),
                    RowParentNodeId: Text(l2.ParentNodeId),
                    RowLevel: 2,
                    RowLabel: Text(l2.DisplayName),
                    RowDescription: Text(l2.Description),
                    RowSortPath: Text(l1.SortOrder, "000") & "." & Text(l2.SortOrder, "000") & ".000",
                    RowIcon: "Section"
                }
            );

            ForAll(
                SortByColumns(
                    Filter(
                        colNodes,
                        IsActive &&
                        LevelNo = 3 &&
                        Text(ParentNodeId) = Text(l2.NodeId)
                    ),
                    "SortOrder",
                    SortOrder.Ascending,
                    "DisplayName",
                    SortOrder.Ascending
                ) As l3,

                Collect(
                    colConfigTreeRows,
                    {
                        RowNodeId: Text(l3.NodeId),
                        RowParentNodeId: Text(l3.ParentNodeId),
                        RowLevel: 3,
                        RowLabel: Text(l3.DisplayName),
                        RowDescription: Text(l3.Description),
                        RowSortPath: Text(l1.SortOrder, "000") & "." & Text(l2.SortOrder, "000") & "." & Text(l3.SortOrder, "000"),
                        RowIcon: "Subsection"
                    }
                )
            )
        )
    );

    Select(btnCfg_RestoreTreeSelection_1);
    Select(btnCfg_BuildAssignedForTarget_1);

    Set(varConfigLoaded, true);
    Set(varCfg_Error, ""),

    Set(varConfigLoaded, false);
    Set(varCfg_Error, First(colCfgErrors).Message);
    Notify(First(colCfgErrors).Message, NotificationType.Error)
);

Set(varCfg_IsLoading, false);
Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingSubMsg, "");
Set(varGlobalLoadingScope, "");

Clear(colAssignedForTarget);
Clear(colAssignedForTargetSummary);
Set(varCfg_Error, "");

With(
    {
        _targetNodeId: Upper(Trim(Text(varTargetSubsectionId))),
        _selL1NodeId: Upper(Trim(Text(varSelNodeId_L1))),
        _selL2NodeId: Upper(Trim(Text(varSelNodeId_L2)))
    },
    If(
        !IsBlank(_targetNodeId),
        With(
            {
                _nodeAssigns:
                    Filter(
                        colAssign,
                        Value(ProjectId) = Value(varProjectId) &&
                        Upper(Trim(Text(NodeId))) = _targetNodeId
                    )
            },
            ClearCollect(
                colAssignedForTarget,
                SortByColumns(
                    AddColumns(
                        Filter(
                            colScope As sc,
                            CountIf(_nodeAssigns, GroupKey = sc.GroupKey) > 0
                        ),
                        AssignedNodeId, _targetNodeId,
                        AssignedNodeName, LookUp(colNodes As nd, Upper(Trim(Text(nd.NodeId))) = _targetNodeId, nd.DisplayName),
                        L1Name, LookUp(colNodes As nd, Upper(Trim(Text(nd.NodeId))) = _selL1NodeId, nd.DisplayName),
                        L2Name, LookUp(colNodes As nd, Upper(Trim(Text(nd.NodeId))) = _selL2NodeId, nd.DisplayName),
                        L3Name, LookUp(colNodes As nd, Upper(Trim(Text(nd.NodeId))) = _targetNodeId, nd.DisplayName)
                    ),
                    "PhaseName", SortOrder.Ascending,
                    "ElementDiscipline", SortOrder.Ascending,
                    "ElementLevel", SortOrder.Ascending,
                    "FormName", SortOrder.Ascending,
                    "FormDescription", SortOrder.Ascending
                )
            );
            ClearCollect(colAssignedForTargetSummary, FirstN(colAssignedForTarget, 4))
        )
    );

    Set(varCfg_SelectedL1Name, Coalesce(LookUp(colNodes As nd, Upper(Trim(Text(nd.NodeId))) = _selL1NodeId, nd.DisplayName), ""));
    Set(varCfg_SelectedL2Name, Coalesce(LookUp(colNodes As nd, Upper(Trim(Text(nd.NodeId))) = _selL2NodeId, nd.DisplayName), ""));
    Set(varCfg_SelectedL3Name, Coalesce(LookUp(colNodes As nd, Upper(Trim(Text(nd.NodeId))) = _targetNodeId, nd.DisplayName), ""));
    Set(varCfg_AssignedCountForTarget, CountRows(colAssignedForTarget));
    Set(varCfg_ReadyForReview, !IsBlank(_targetNodeId) && CountRows(colAssignedForTarget) > 0)
);

Set(varCfg_Error, "");

If(
    !IsBlank(Text(varLastSavedNodeId)),
    With(
        {
            n: LookUp(
                colNodes,
                Text(NodeId) = Text(varLastSavedNodeId)
            )
        },
        If(
            !IsBlank(Text(n.NodeId)) && Value(n.LevelNo) = 1,
            Set(varSelNodeId_L1, Text(n.NodeId));
            Set(varSelNodeId_L2, "");
            Set(varSelNodeId_L3, ""),

            If(
                !IsBlank(Text(n.NodeId)) && Value(n.LevelNo) = 2,
                Set(varSelNodeId_L1, Text(n.ParentNodeId));
                Set(varSelNodeId_L2, Text(n.NodeId));
                Set(varSelNodeId_L3, ""),

                If(
                    !IsBlank(Text(n.NodeId)) && Value(n.LevelNo) = 3,
                    With(
                        {
                            n2: LookUp(
                                colNodes,
                                Text(NodeId) = Text(n.ParentNodeId)
                            )
                        },
                        With(
                            {
                                n1: LookUp(
                                    colNodes,
                                    Text(NodeId) = Text(n2.ParentNodeId)
                                )
                            },
                            Set(varSelNodeId_L1, Text(n1.NodeId));
                            Set(varSelNodeId_L2, Text(n2.NodeId));
                            Set(varSelNodeId_L3, Text(n.NodeId))
                        )
                    )
                )
            )
        )
    )
);

Select(btnCfg_RefreshSelectionContext_1)

Set(varSelectedNodeId, Coalesce(varSelNodeId_L3, varSelNodeId_L2, varSelNodeId_L1));
Set(varSelectedNode, LookUp(colNodes, Text(NodeId) = Text(varSelectedNodeId)));
Set(varSelectedNodeLevel, If(IsBlank(varSelectedNode.NodeId), 0, Value(varSelectedNode.LevelNo)));
Set(varSelectedNodeName, Coalesce(varSelectedNode.DisplayName, ""));
Set(varSelectedParentName, Coalesce(LookUp(colNodes, Text(NodeId) = Text(varSelectedNode.ParentNodeId), DisplayName), ""));
Set(varSelectedNodeIsActive, If(IsBlank(varSelectedNode.NodeId), false, Boolean(varSelectedNode.IsActive)));
Set(varTargetSubsectionId, varSelNodeId_L3);
Set(varTargetSubsectionName, If(IsBlank(varSelNodeId_L3), "", LookUp(colNodes, Text(NodeId) = Text(varSelNodeId_L3), DisplayName)));
Select(btnCfg_BuildAssignedForTarget_1);

ControlPropertyState.AutoRuleBindingString:
Set(varScopeModalLoading, true);
Clear(colScopeModalAssigned);
Clear(colScopeModalAvailable);
Clear(colScopeModalAssignedElsewhere);
Clear(colScopeModalWorking);
ClearCollect(colScopeModalSelected, FirstN(colScope, 0));
With(
    {
        _targetNodeId: Upper(Trim(Text(varTargetSubsectionId))),
        _nodeAssignsCurrent: Filter(colAssign, Value(ProjectId) = Value(varProjectId) && Upper(Trim(Text(NodeId))) = Upper(Trim(Text(varTargetSubsectionId)))),
        _allAssigns: Filter(colAssign, Value(ProjectId) = Value(varProjectId))
    },
    ClearCollect(
        colScopeModalAssigned,
        SortByColumns(
            AddColumns(
                Filter(colScope As sc, CountIf(_nodeAssignsCurrent, GroupKey = sc.GroupKey) > 0),
                AssignedNodeId, _targetNodeId,
                AssignedL1, varCfg_SelectedL1Name,
                AssignedL2, varCfg_SelectedL2Name,
                AssignedL3, varCfg_SelectedL3Name
            ),
            "PhaseName", SortOrder.Ascending,
            "ElementDiscipline", SortOrder.Ascending,
            "ElementLevel", SortOrder.Ascending,
            "FormName", SortOrder.Ascending,
            "FormDescription", SortOrder.Ascending
        )
    );
    ClearCollect(
        colScopeModalAvailable,
        SortByColumns(
            Filter(colScope As sc, CountIf(_allAssigns, GroupKey = sc.GroupKey) = 0),
            "PhaseName", SortOrder.Ascending,
            "ElementDiscipline", SortOrder.Ascending,
            "ElementLevel", SortOrder.Ascending,
            "FormName", SortOrder.Ascending,
            "FormDescription", SortOrder.Ascending
        )
    )
);
ClearCollect(
    colScopeModalWorking,
    Switch(Coalesce(varScopeModalMode, "assigned"), "assigned", colScopeModalAssigned, "available", colScopeModalAvailable, colScopeModalAssigned)
);
Set(varScopeModalLoading, false);

Rules.InvariantScript:
If(
    IsBlank(varProjectId) || !IsNumeric(Text(varProjectId)),
    Notify("Select a valid project first.", NotificationType.Warning);
    Exit()
);
Set(varCfgPunches_IsApplying, true);
Set(varGlobalLoading, true);
Set(varGlobalLoadingMsg, "Applying Punch configuration...");
Set(varGlobalLoadingSubMsg, "Regenerating Overview snapshot");
Set(varGlobalLoadingScope, "CONFIG");
IfError(
    warroom_GenerateOverviewSnapshot.Run(Value(varProjectId));
    Notify("Punch configuration applied to Overview.", NotificationType.Success),
    Notify("Could not apply Punch configuration to Overview.", NotificationType.Error)
);
Set(varCfgPunches_IsApplying, false);
Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingSubMsg, "");
Set(varGlobalLoadingScope, "")

IfError(
    Warroom_SetPunchReportStatusIncluded.Run(Value(varProjectId), ThisItem.StatusCode, Self.Value, User().Email);
    Patch(colCfgPunchStatuses, ThisItem, {IsIncluded: Self.Value}),
    Notify("Status configuration could not be saved.", NotificationType.Error);
    Reset(Self)
)

Set(varCfgPunches_IsSaving, true);
IfError(
    Warroom_SetPunchTemplateIncluded.Run(Value(varProjectId), Value(ThisItem.TemplateId), Self.Value, Value(ThisItem.DisplayOrder), User().Email);
    Patch(colCfgPunchTemplates, LookUp(colCfgPunchTemplates, TemplateId = ThisItem.TemplateId), {IsIncluded: Self.Value, ConfigExists: true}),
    Notify("Template configuration could not be saved.", NotificationType.Error);
    Reset(Self)
);
Set(varCfgPunches_IsSaving, false)

Set(varEditMode, "NEW");
Set(varEditLevel, 1);
Set(varEditParentNodeId, "");
Set(varEditNodeId, "");
Set(varTmp_DisplayName, "");
Set(varTmp_Description, "");
Set(varTmp_SqlKey, "");
Set(varTmp_GridKey, "");
Set(varTmp_SortOrder, 0);
Set(varTmp_IsActive, true);
Set(varNodeModalOpen, true)

Switch(
    Value(ThisItem.RowLevel),

    1,
        Set(varSelNodeId_L1, Text(ThisItem.RowNodeId));
        Set(varSelNodeId_L2, "");
        Set(varSelNodeId_L3, "");
        Set(varTargetSubsectionId, "");
        Set(varTargetSubsectionName, ""),

    2,
        Set(varSelNodeId_L2, Text(ThisItem.RowNodeId));
        Set(varSelNodeId_L1, Text(ThisItem.RowParentNodeId));
        Set(varSelNodeId_L3, "");
        Set(varTargetSubsectionId, "");
        Set(varTargetSubsectionName, ""),

    3,
        Set(varSelNodeId_L3, Text(ThisItem.RowNodeId));
        Set(varTargetSubsectionId, Text(ThisItem.RowNodeId));
        Set(varTargetSubsectionName, Text(ThisItem.RowLabel));

        With(
            {
                n2: LookUp(
                    colNodes,
                    Text(NodeId) = Text(ThisItem.RowParentNodeId)
                )
            },
            With(
                {
                    n1: LookUp(
                        colNodes,
                        Text(NodeId) = Text(n2.ParentNodeId)
                    )
                },
                Set(varSelNodeId_L1, Text(n1.NodeId));
                Set(varSelNodeId_L2, Text(n2.NodeId))
            )
        )
);

Select(btnCfg_RefreshSelectionContext_1)

ControlPropertyState.AutoRuleBindingString:
Switch(
    Value(ThisItem.LevelNo),
    1,
        Set(varSelNodeId_L1, Text(ThisItem.NodeId));
        Set(varSelNodeId_L2, "");
        Set(varSelNodeId_L3, "");
        Set(varTargetSubsectionId, "");
        Set(varTargetSubsectionName, ""),
    2,
        Set(varSelNodeId_L2, Text(ThisItem.NodeId));
        Set(varSelNodeId_L1, Text(ThisItem.ParentNodeId));
        Set(varSelNodeId_L3, "");
        Set(varTargetSubsectionId, "");
        Set(varTargetSubsectionName, ""),
    3,
        Set(varSelNodeId_L3, Text(ThisItem.NodeId));
        Set(varTargetSubsectionId, Text(ThisItem.NodeId));
        Set(varTargetSubsectionName, ThisItem.DisplayName);
        With(
            {n2: LookUp(colNodes, Text(NodeId) = Text(ThisItem.ParentNodeId))},
            With(
                {n1: LookUp(colNodes, Text(NodeId) = Text(n2.ParentNodeId))},
                Set(varSelNodeId_L1, Text(n1.NodeId));
                Set(varSelNodeId_L2, Text(n2.NodeId))
            )
        )
);
Select(btnCfg_RefreshSelectionContext_1)

Rules.InvariantScript:
If(
    IsBlank(varTargetSubsectionId),
    Notify("Select a Level 3 subsection first.", NotificationType.Warning),

    Set(varScopeModalLoading, true);
    Set(varScopeModalOpen, true);
    Set(varScopeModalSearch, "");
    Clear(colScopeModalSelectedAvailable);
    Clear(colScopeModalSelectedAssigned);

    Select(btnScopeModal_LoadData_Config_1);

    Set(varScopeModalLoading, false)
);

ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(varTargetSubsectionId),
    Notify("Select a Level 3 subsection first.", NotificationType.Warning),
    Set(varScopeModalLoading, true);
    Set(varScopeModalMode, "assigned");
    Set(varScopeModalSearch, "");
    ClearCollect(colScopeModalSelected, FirstN(colScope, 0));
    Select(btnCfg_BuildAssignedForTarget_1);
    Select(btnScopeModal_RebuildLocal_Config_1);
    Set(varScopeModalOpen, true);
    Set(varScopeModalLoading, false)
);

Rules.InvariantScript:
"To assign: " &
Text(
    CountRows(
        Filter(
            colScopeModalAssigned As a,
            CountIf(
                colScopeModalOriginalAssigned,
                GroupKey = a.GroupKey
            ) = 0
        )
    )
) &
" · To remove: " &
Text(
    CountRows(
        Filter(
            colScopeModalOriginalAssigned As o,
            CountIf(
                colScopeModalAssigned,
                GroupKey = o.GroupKey
            ) = 0
        )
    )
)

Set(varScopeConfirmCloseOpen, false);
Set(varScopeModalOpen, false);
Set(varScopeModalSearch, "");
Set(varScopeModalDirty, false);
Clear(colScopeModalSelectedAvailable);
Clear(colScopeModalSelectedAssigned)

If(
    varScopeModalDirty,
    Set(varScopeConfirmCloseOpen, true),
    Set(varScopeModalOpen, false);
    Set(varScopeModalSearch, "");
    Set(varScopeModalDirty, false);
    Clear(colScopeModalSelectedAvailable);
    Clear(colScopeModalSelectedAssigned)
)

If(
    varScopeModalDirty,
    Set(varScopeConfirmCloseOpen, true),
    Set(varScopeModalOpen, false);
    Set(varScopeModalSearch, "");
    Set(varScopeModalDirty, false);
    Clear(colScopeModalSelectedAvailable);
    Clear(colScopeModalSelectedAssigned)
)

If(
    varSelectedNodeLevel <> 3 || IsBlank(varTargetSubsectionId),
    Notify("Assignments can only be saved for a Level 3 subsection.", NotificationType.Warning);
    Exit()
);

If(
    CountRows(colScopeModalAssigned) <>
    CountRows(Distinct(colScopeModalAssigned, GroupKey)),
    Notify("Duplicated assignment detected. Reload the modal before saving.", NotificationType.Error);
    Exit()
);

Set(varScopeModalError, "");
Set(varScopeModalLoading, true);

ClearCollect(
    colScopeModalToAssign,
    Filter(
        colScopeModalAssigned As a,
        CountIf(
            colScopeModalOriginalAssigned,
            GroupKey = a.GroupKey
        ) = 0
    )
);

ClearCollect(
    colScopeModalToUnassign,
    Filter(
        colScopeModalOriginalAssigned As o,
        CountIf(
            colScopeModalAssigned,
            GroupKey = o.GroupKey
        ) = 0
    )
);

Set(
    varScopeModalAssignKeys,
    Concat(
        colScopeModalToAssign,
        GroupKey,
        "|"
    )
);

Set(
    varScopeModalUnassignKeys,
    Concat(
        colScopeModalToUnassign,
        GroupKey,
        "|"
    )
);

If(
    !IsBlank(varScopeModalAssignKeys),
    WarRoom_ReportConfig_AssignGroups.Run(
        Value(varProjectId),
        Text(varTargetSubsectionId),
        varScopeModalAssignKeys,
        User().Email
    )
);

If(
    !IsBlank(varScopeModalUnassignKeys),
    Warroom_ReportConfig_UnassignGroups.Run(
        Value(varProjectId),
        Text(varTargetSubsectionId),
        varScopeModalUnassignKeys
    )
);

ClearCollect(
    colAssign,
    ForAll(
        Table(
            ParseJSON(
                Coalesce(
                    WarRoom_ReportConfig_GetAssignments.Run(varProjectId).result,
                    "[]"
                )
            )
        ),
        {
            AssignmentId: Text(Value.AssignmentId),
            ProjectId:
                If(
                    IsBlank(Text(Value.ProjectId)) || Text(Value.ProjectId) = "null",
                    varProjectId,
                    Value(Text(Value.ProjectId))
                ),
            GroupKey: Text(Value.GroupKey),
            NodeId: Text(Value.NodeId),
            CreatedOn: Text(Value.CreatedOn),
            CreatedBy: Text(Value.CreatedBy)
        }
    )
);

Select(btnCfg_BuildAssignedForTarget_1);

Set(varScopeModalOpen, false);
Set(varScopeModalSearch, "");
Set(varScopeModalDirty, false);
Set(varScopeConfirmCloseOpen, false);

ClearCollect(colScopeModalSelectedAvailable, colScopeModalSchema);
ClearCollect(colScopeModalSelectedAssigned, colScopeModalSchema);

Notify("Assignments saved successfully.", NotificationType.Success);

Set(varScopeModalLoading, false);

"To assign: " &
Text(
    CountRows(
        Filter(
            colScopeModalAssigned,
            CountIf(
                colScopeModalOriginalAssigned,
                GroupKey = colScopeModalAssigned[@GroupKey]
            ) = 0
        )
    )
) &
" · To remove: " &
Text(
    CountRows(
        Filter(
            colScopeModalOriginalAssigned,
            CountIf(
                colScopeModalAssigned,
                GroupKey = colScopeModalOriginalAssigned[@GroupKey]
            ) = 0
        )
    )
) &
" · Selected: " &
Text(
    CountRows(colScopeModalSelectedAvailable) +
    CountRows(colScopeModalSelectedAssigned)
)

ForAll(
    colScopeModalSelectedAvailable As sel,
    If(
        CountIf(
            colScopeModalAssigned,
            GroupKey = sel.GroupKey
        ) = 0,
        Collect(
            colScopeModalAssigned,
            sel
        )
    )
);

RemoveIf(
    colScopeModalAvailable,
    CountIf(
        colScopeModalSelectedAvailable,
        GroupKey = colScopeModalAvailable[@GroupKey]
    ) > 0
);

Clear(colScopeModalSelectedAvailable);
Set(varScopeModalDirty, true)

ControlPropertyState.AutoRuleBindingString:
Collect(colScopeModalAssigned, colScopeModalSelectedAvailable);
RemoveIf(
    colScopeModalAvailable,
    CountIf(colScopeModalSelectedAvailable, GroupKey = colScopeModalAvailable[@GroupKey]) > 0
);
Clear(colScopeModalSelectedAvailable)

Rules.InvariantScript:
ForAll(
    colScopeModalSelectedAssigned As sel,
    If(
        CountIf(
            colScopeModalAvailable,
            GroupKey = sel.GroupKey
        ) = 0,
        Collect(
            colScopeModalAvailable,
            sel
        )
    )
);

RemoveIf(
    colScopeModalAssigned,
    CountIf(
        colScopeModalSelectedAssigned,
        GroupKey = colScopeModalAssigned[@GroupKey]
    ) > 0
);

Clear(colScopeModalSelectedAssigned);
Set(varScopeModalDirty, true)

ControlPropertyState.AutoRuleBindingString:
Collect(colScopeModalAvailable, colScopeModalSelectedAssigned);
RemoveIf(
    colScopeModalAssigned,
    CountIf(colScopeModalSelectedAssigned, GroupKey = colScopeModalAssigned[@GroupKey]) > 0
);
Clear(colScopeModalSelectedAssigned)

Rules.InvariantScript:
Set(varScopeModalError, "");
Set(varScopeModalLoading, true);
Set(varScopeModalDirty, false);
Set(varScopeConfirmCloseOpen, false);

ClearCollect(colScopeModalTarget, FirstN(colScopeModalTarget, 0));
ClearCollect(colScopeModalAvailable, colScopeModalSchema);
ClearCollect(colScopeModalAssigned, colScopeModalSchema);
ClearCollect(colScopeModalOriginalAssigned, colScopeModalSchema);
ClearCollect(colScopeModalSelectedAvailable, colScopeModalSchema);
ClearCollect(colScopeModalSelectedAssigned, colScopeModalSchema);

IfError(
    With(
        {
            r: Warroom_ReportConfig_GetAssignmentModalData.Run(
                Value(varProjectId),
                Text(varTargetSubsectionId)
            )
        },
        ClearCollect(
            colScopeModalTarget,
            ForAll(
                Table(ParseJSON(Coalesce(r.result, "{}"))),
                {
                    NodeId: Text(Value.NodeId),
                    L1DisplayName: Text(Value.L1DisplayName),
                    L2DisplayName: Text(Value.L2DisplayName),
                    L3DisplayName: Text(Value.L3DisplayName),
                    AssignedCount:
                        If(
                            IsBlank(Text(Value.AssignedCount)) || Text(Value.AssignedCount) = "null",
                            0,
                            Value(Text(Value.AssignedCount))
                        ),
                    AvailableCount:
                        If(
                            IsBlank(Text(Value.AvailableCount)) || Text(Value.AvailableCount) = "null",
                            0,
                            Value(Text(Value.AvailableCount))
                        )
                }
            )
        );

        ClearCollect(
            colScopeModalAssigned,
            ForAll(
                Table(ParseJSON(Coalesce(r.result, "[]"))),
                {
                    GroupKey: Text(Value.GroupKey),
                    PhaseName: Text(Value.PhaseName),
                    ElementDiscipline: Text(Value.ElementDiscipline),
                    ElementLevel: Text(Value.ElementLevel),
                    FormName: Text(Value.FormName),
                    FormDescription: Text(Value.FormDescription),
                    Sct: Lower(Text(Value.Sct)) = "true" || Text(Value.Sct) = "1",
                    MasterTask: Lower(Text(Value.MasterTask)) = "true" || Text(Value.MasterTask) = "1",
                    DossierTask: Lower(Text(Value.DossierTask)) = "true" || Text(Value.DossierTask) = "1",
                    TotalInspections:
                        If(
                            IsBlank(Text(Value.TotalInspections)) || Text(Value.TotalInspections) = "null",
                            0,
                            Value(Text(Value.TotalInspections))
                        ),
                    AssignedNodeId: Text(Value.AssignedNodeId),
                    L1DisplayName: Text(Value.L1DisplayName),
                    L2DisplayName: Text(Value.L2DisplayName),
                    L3DisplayName: Text(Value.L3DisplayName)
                }
            )
        );

        ClearCollect(colScopeModalOriginalAssigned, colScopeModalAssigned);

        ClearCollect(
            colScopeModalAvailable,
            ForAll(
                Table(ParseJSON(Coalesce(r.result, "[]"))),
                {
                    GroupKey: Text(Value.GroupKey),
                    PhaseName: Text(Value.PhaseName),
                    ElementDiscipline: Text(Value.ElementDiscipline),
                    ElementLevel: Text(Value.ElementLevel),
                    FormName: Text(Value.FormName),
                    FormDescription: Text(Value.FormDescription),
                    Sct: Lower(Text(Value.Sct)) = "true" || Text(Value.Sct) = "1",
                    MasterTask: Lower(Text(Value.MasterTask)) = "true" || Text(Value.MasterTask) = "1",
                    DossierTask: Lower(Text(Value.DossierTask)) = "true" || Text(Value.DossierTask) = "1",
                    TotalInspections:
                        If(
                            IsBlank(Text(Value.TotalInspections)) || Text(Value.TotalInspections) = "null",
                            0,
                            Value(Text(Value.TotalInspections))
                        ),
                    AssignedNodeId: "",
                    L1DisplayName: "",
                    L2DisplayName: "",
                    L3DisplayName: ""
                }
            )
        )
    ),
    Set(varScopeModalError, FirstError.Message);
    ClearCollect(colScopeModalAvailable, colScopeModalSchema);
    ClearCollect(colScopeModalAssigned, colScopeModalSchema);
    ClearCollect(colScopeModalOriginalAssigned, colScopeModalSchema);
    Notify(
        "Assignment modal data could not be loaded: " & FirstError.Message,
        NotificationType.Error
    )
);

Set(varScopeModalLoading, false)

ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(varProjectId),
    Notify("Please select a project first.", NotificationType.Warning);
    Exit()
);

Set(varCfgPunches_IsLoading, true);
Set(varCfgPunches_Error, "");
Clear(colCfgPunchTemplates);

IfError(
    With(
        {resp: Warroom_GetProjectPunchTemplates.Run(Value(varProjectId))},
        ClearCollect(
            colCfgPunchTemplates,
            ForAll(
                Table(ParseJSON(Coalesce(resp.result, "[]"))),
                {
                    ProjectId: Value(Text(Value.ProjectId)),
                    TemplateId: Value(Text(Value.TemplateId)),
                    TemplateCode: Text(Value.TemplateCode),
                    TemplateName: Text(Value.TemplateName),
                    TemplateDisplayName: Text(Value.TemplateDisplayName),
                    TemplateIsActive: Lower(Text(Value.TemplateIsActive)) = "true" || Text(Value.TemplateIsActive) = "1",
                    TemplateProjectIsActive: Lower(Text(Value.TemplateProjectIsActive)) = "true" || Text(Value.TemplateProjectIsActive) = "1",
                    TemplateProjectClosed: Lower(Text(Value.TemplateProjectClosed)) = "true" || Text(Value.TemplateProjectClosed) = "1",
                    CategoryCount: If(IsBlank(Text(Value.CategoryCount)) || Text(Value.CategoryCount) = "null", 0, Value(Text(Value.CategoryCount))),
                    CategoriesSummary: Text(Value.CategoriesSummary),
                    TemplateColorIndex: Mod(If(IsBlank(Text(Value.DisplayOrder)) || Text(Value.DisplayOrder) = "null", 1, Value(Text(Value.DisplayOrder))) - 1, 6) + 1,
                    TemplateChipBg: Switch(Mod(If(IsBlank(Text(Value.DisplayOrder)) || Text(Value.DisplayOrder) = "null", 1, Value(Text(Value.DisplayOrder))) - 1, 6) + 1, 1, ColorValue("#E0F7FF"), 2, ColorValue("#EEF2FF"), 3, ColorValue("#F3E8FF"), 4, ColorValue("#ECFDF5"), 5, ColorValue("#FFF7ED"), 6, ColorValue("#F8FAFC"), ColorValue("#E0F7FF")),
                    TemplateChipFg: Switch(Mod(If(IsBlank(Text(Value.DisplayOrder)) || Text(Value.DisplayOrder) = "null", 1, Value(Text(Value.DisplayOrder))) - 1, 6) + 1, 1, ColorValue("#1677FF"), 2, ColorValue("#4F46E5"), 3, ColorValue("#9333EA"), 4, ColorValue("#059669"), 5, ColorValue("#EA580C"), 6, ColorValue("#475569"), ColorValue("#1677FF")),
                    TotalPunches: If(IsBlank(Text(Value.TotalPunches)) || Text(Value.TotalPunches) = "null", 0, Value(Text(Value.TotalPunches))),
                    OpenPunches: If(IsBlank(Text(Value.OpenPunches)) || Text(Value.OpenPunches) = "null", 0, Value(Text(Value.OpenPunches))),
                    ClearedPunches: If(IsBlank(Text(Value.ClearedPunches)) || Text(Value.ClearedPunches) = "null", 0, Value(Text(Value.ClearedPunches))),
                    ClosedPunches: If(IsBlank(Text(Value.ClosedPunches)) || Text(Value.ClosedPunches) = "null", 0, Value(Text(Value.ClosedPunches))),
                    IsIncluded: Lower(Text(Value.IsIncluded)) = "true" || Text(Value.IsIncluded) = "1",
                    DisplayOrder: If(IsBlank(Text(Value.DisplayOrder)) || Text(Value.DisplayOrder) = "null", 0, Value(Text(Value.DisplayOrder))),
                    ConfigExists: Lower(Text(Value.ConfigExists)) = "true" || Text(Value.ConfigExists) = "1"
                }
            )
        )
    ),
    Set(varCfgPunches_Error, FirstError.Message);
    Notify("Punch templates could not be loaded.", NotificationType.Error)
);

Set(varCfgPunches_Loaded, true);
Set(varCfgPunches_IsLoading, false)

Rules.InvariantScript:
If(
    IsBlank(varProjectId),
    Notify("Please select a project first.", NotificationType.Warning);
    Exit()
);

Set(varCfgPunches_StatusError, "");

ClearCollect(
    colCfgPunchStatuses,
    FirstN(
        Table(
            {
                ProjectId: 0,
                StatusCode: "",
                IsIncluded: false,
                DisplayOrder: 0
            }
        ),
        0
    )
);

IfError(
    ClearCollect(
        colCfgPunchStatuses,
        ForAll(
            Table(
                ParseJSON(
                    Coalesce(
                        Warroom_GetPunchReportStatusConfig.Run(Value(varProjectId)).result,
                        "[]"
                    )
                )
            ),
            {
                ProjectId:
                    If(
                        IsBlank(Text(Value.ProjectId)) ||
                        Text(Value.ProjectId) = "null",
                        Value(varProjectId),
                        Value(Text(Value.ProjectId))
                    ),

                StatusCode: Text(Value.StatusCode),

                IsIncluded:
                    Lower(Text(Value.IsIncluded)) = "true" ||
                    Text(Value.IsIncluded) = "1",

                DisplayOrder:
                    If(
                        IsBlank(Text(Value.DisplayOrder)) ||
                        Text(Value.DisplayOrder) = "null",
                        0,
                        Value(Text(Value.DisplayOrder))
                    )
            }
        )
    ),

    Set(varCfgPunches_StatusError, FirstError.Message);
    ClearCollect(
        colCfgPunchStatuses,
        FirstN(colCfgPunchStatuses, 0)
    )
);

If(
    !IsBlank(varCfgPunches_StatusError),
    Notify(
        "Punch status configuration could not be loaded: " & varCfgPunches_StatusError,
        NotificationType.Error
    )
);

ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(varProjectId),
    Notify("Please select a project first.", NotificationType.Warning);
    Exit()
);

IfError(
    ClearCollect(
        colCfgPunchStatuses,
        ForAll(
            Table(ParseJSON(Coalesce(Warroom_GetPunchReportStatusConfig.Run(Value(varProjectId)).result, "[]"))),
            {
                ProjectId: Value(Text(Value.ProjectId)),
                StatusCode: Text(Value.StatusCode),
                IsIncluded: Lower(Text(Value.IsIncluded)) = "true" || Text(Value.IsIncluded) = "1",
                DisplayOrder: If(IsBlank(Text(Value.DisplayOrder)) || Text(Value.DisplayOrder) = "null", 0, Value(Text(Value.DisplayOrder)))
            }
        )
    ),
    Notify("Punch status configuration could not be loaded.", NotificationType.Error)
)
